const nrelData = $input.first().json.outputs;

// Get bill amount from input
const monthlyBill = $input.first().json['Monthly Electric Bill ($)'] || 
                    $json['Monthly Electric Bill ($)'] || 
                    200;

// Calculate system size
const systemCapacity = monthlyBill < 100 ? 3 :
  monthlyBill < 150 ? 5 :
  monthlyBill < 250 ? 7 :
  monthlyBill < 350 ? 10 : 12;

// Calculate deal value
const dealValue = monthlyBill < 100 ? 15000 :
  monthlyBill < 200 ? 25000 :
  monthlyBill < 350 ? 35000 : 45000;

// Extract NREL data
const annualProduction = Math.round(nrelData.ac_annual);
const dailySunHours = nrelData.solrad_annual.toFixed(1);
const systemEfficiency = nrelData.capacity_factor.toFixed(1);

// Calculate savings
const annualSavings = Math.round(annualProduction * 0.13);
const monthlySavings = Math.round(annualSavings / 12);
const savings20yr = annualSavings * 20;

// Calculate payback
const paybackYears = (dealValue / annualSavings).toFixed(1);

// Return ONLY essential fields
return [{
  json: {
    systemCapacity: systemCapacity + ' kW',
    dailySunHours: dailySunHours + ' hrs',
    annualProduction: annualProduction.toLocaleString() + ' kWh',
    systemEfficiency: systemEfficiency + '%',
    monthlySavings: '$' + monthlySavings.toLocaleString(),
    annualSavings: '$' + annualSavings.toLocaleString(),
    savings20yr: '$' + savings20yr.toLocaleString(),
    dealValue: '$' + dealValue.toLocaleString(),
    paybackYears: paybackYears + ' years',
    monthlySavingsRaw: monthlySavings,
    annualSavingsRaw: annualSavings,
    savings20yrRaw: savings20yr,
    dealValueRaw: dealValue,
    monthlyBillRaw: monthlyBill
  }
}];

