  const line = lines[i];

  // Skip empty lines
  if (line === '') {
    // If we have accumulated paragraph text, save it
    if (currentParagraph.length > 0) {
      formattedLines.push(currentParagraph.join(' '));
      currentParagraph = [];
    }
    // Add blank line for spacing
    formattedLines.push('');
    continue;
  }

  // Detect section headers (lines with colons, all caps, or special markers)
  const isHeader = (
    line.endsWith(':') ||
    line === line.toUpperCase() && line.length < 50 ||
    line.startsWith('━') ||
    line.startsWith('•') ||
    /^[A-Z\s]{10,}$/.test(line)
  );

