      currentParagraph = [];
    }
    // Add list item as standalone
    formattedLines.push(line);
    continue;
  }

  // SHORT LINE (under 60 chars) - likely intentional formatting
  if (line.length < 60) {
    // Save current paragraph
    if (currentParagraph.length > 0) {
      formattedLines.push(currentParagraph.join(' '));
      currentParagraph = [];
    }
    // Add short line standalone
    formattedLines.push(line);
    continue;
  }

  // LONG LINE (60+ chars) - accumulate into paragraph
  currentParagraph.push(line);

