  .replace(/!{2,}/g, '!')
  .replace(/\?{2,}/g, '?')

  // Ensure proper spacing after sentences
  .replace(/([.!?])([A-Z])/g, '$1 $2')

  // Remove any remaining control characters
  .replace(/[\x00-\x1F\x7F]/g, '')

  // Final trim
  .trim();

