// ====================================================================

// Ensure not too many consecutive blank lines
finalText = finalText.replace(/\n{4,}/g, '\n\n\n');

// Ensure no weird spacing at start/end
finalText = finalText.trim();

// If text is suspiciously short, flag it
const tooShort = finalText.length < 50;
const tooLong = finalText.length > 5000;

console.log('✅ Formatted text length:', finalText.length);
console.log('📊 Formatting stats:', {
